  "brain.py": "\"\"\"Building a Neuron - the brain. `python brain.py` runs it.\n\n    python brain.py \"Say hello to a project called Cosmonapse in one line.\"\n    python brain.py                       # REPL\n\nNeuron -> Axon -> Dendrite -> TASK -> reply. neurons/greeter.py holds the\nNeuron and its Axon, receptors/terminal.py is the interface, and this file\nis deployment: which node hosts what. No broker - the default synapse is\nin-process.\n\"\"\"\nimport asyncio\nimport contextlib\nimport signal\n\nfrom cosmonapse import Dendrite, MemorySynapse, connect_synapse, run_brain\n\nfrom config import NAMESPACE, SYNAPSE_URL\nfrom neurons import greeter\nfrom receptors import terminal\n\n\ndef build_greeter(synapse) -> Dendrite:\n    \"\"\"Hosts the greeter Axon. role=\"worker\" is a protocol guard: a worker\n    serves TASKs and bids, but cannot emit TASK / FINAL / STOP.\"\"\"\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=\"greeter-node\", role=\"worker\")\n    node.attach_axon(greeter.AXON)\n    return node\n\n\ndef build_terminal(synapse) -> Dendrite:\n    \"\"\"Hosts the Receptor. It originates TASKs, so it needs an\n    orchestrator-role node of its own.\"\"\"\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=\"terminal-node\", heartbeat_s=0)\n    node.attach_receptor(terminal.RECEPTOR)\n    return node\n\n\ndef _stop_on_signals() -> None:\n    \"\"\"Ctrl-C / SIGTERM cancel the task so run_brain can unwind every node.\"\"\"\n    task = asyncio.current_task()\n    loop = asyncio.get_running_loop()\n    for sig in (signal.SIGINT, signal.SIGTERM):\n        with contextlib.suppress(NotImplementedError, AttributeError):\n            loop.add_signal_handler(sig, task.cancel)\n\n\nasync def main() -> int:\n    _stop_on_signals()\n    if SYNAPSE_URL:\n        synapse = await connect_synapse(SYNAPSE_URL)\n    else:\n        synapse = MemorySynapse()      # in-process bus - no broker, no setup\n        await synapse.connect()\n    try:\n        return await run_brain(build_greeter(synapse), build_terminal(synapse))\n    except asyncio.CancelledError:\n        return 0\n    finally:\n        await synapse.close()\n\n\nif __name__ == \"__main__\":\n    try:\n        raise SystemExit(asyncio.run(main()))\n    except KeyboardInterrupt:\n        raise SystemExit(130)\n",
  "config.py": "\"\"\"Shared settings for the building-a-neuron package.\"\"\"\nimport os\nfrom pathlib import Path\n\nfrom dotenv import load_dotenv\n\nROOT = Path(__file__).resolve().parent\nload_dotenv(ROOT.parent / \".env\")               # cosmonapse-examples/.env\n\n# Unset -> brain.py runs on an in-process MemorySynapse (no broker, no\n# setup). Set it (e.g. cosmo://127.0.0.1:7070) to run over a real synapse.\nSYNAPSE_URL = os.environ.get(\"SYNAPSE_URL\", \"\")\nNAMESPACE = \"demo\"\n\n\ndef hf_token() -> str:\n    token = os.environ.get(\"HF_TOKEN\", \"\")\n    if not token:\n        raise RuntimeError(\"Set HF_TOKEN in cosmonapse-examples/.env\")\n    return token\n",
  "neurons/greeter.py": "\"\"\"greeter - one HF chat Neuron behind an Axon.\n\nA Neuron is anything that satisfies the NeuronFn contract:\n  async fn(input, context) -> output\nThe unified factory wraps any source behind that interface. Here it's\na HuggingFace endpoint; it could equally be Ollama, OpenAI, or an MCP\nserver - the Axon never knows the difference.\n\nInput the orchestrator sends: {\"prompt\": \"...\"} or {\"messages\": [...]}\nOutput the Neuron returns:    {\"response\": \"<text>\", \"meta\": <raw>}\n\"\"\"\nfrom cosmonapse import Axon, Neuron\n\nfrom config import hf_token\n\ngreeter = Neuron(\n    source=\"huggingface\",\n    endpoint=\"https://router.huggingface.co\",\n    model=\"meta-llama/Llama-3.1-8B-Instruct\",\n    api_key=hf_token(),\n    use_chat_api=True,\n    max_new_tokens=128,\n    temperature=0.7,\n)\n\n# The Axon declares identity + capabilities and owns the Neuron.\nAXON = Axon(\n    neuron_id=\"greeter\",\n    neuron_fn=greeter,\n    capabilities=[\"text-generation\", \"chat\", \"greet\"],\n)\n\n# Swapping providers - the endpoint is the only HF-specific line:\n#   endpoint=\"https://<your-endpoint>.endpoints.huggingface.cloud\"  # dedicated HF\n#   endpoint=\"http://localhost:8080\"            # local TGI / vLLM / LM Studio\n# For Ollama, switch source - same Axon, same Dendrite:\n#   greeter = Neuron(source=\"ollama\", model=\"llama3\")\n",
  "receptors/terminal.py": "\"\"\"terminal - a CliReceptor: a line typed at a shell becomes a TASK.\n\n    python brain.py \"Say hello to a project called Cosmonapse in one line.\"\n    python brain.py                       # REPL\n\nThe command function returns the TASK input - that is the whole contract.\nThe argparse tree, the REPL, and the dispatch-and-wait are the Receptor's.\nBuilt with no dendrite= on purpose; brain.py binds it.\n\"\"\"\nfrom cosmonapse import CliReceptor, SignalType\n\nRECEPTOR = CliReceptor(\n    neuron=\"greeter\",\n    prog=\"greeter\",\n    description=\"Ask the greeter Neuron for a one-liner.\",\n    timeout_s=30.0,\n)\n\n\n@RECEPTOR.command(help=\"send a prompt to the greeter\")\ndef ask(prompt: str):\n    return {\"prompt\": prompt}          # <- the TASK input\n\n\n@RECEPTOR.on_result\ndef render(sig):\n    # The HF Neuron returns {\"response\": \"<text>\", \"meta\": <raw>}.\n    if sig.type is SignalType.ERROR:\n        return f\"[ERROR] {sig.payload.get('message')}\"\n    return f\"[{sig.type.value}] {sig.payload['output']['response'].strip()}\"\n"
